	/** 
	 * jumpstart the process by instantiating2 Quote
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		quoteId = QuoteService.getQuoteInstance()
		.createQuote( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		QuoteService.getQuoteInstance()
				.createQuote( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.quoteSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Quote : " + successValue.getQuoteId());
							  if (successValue.getQuoteId().equals(quoteId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfQuoteList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Quote test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on quote consumed")
					);
			subscriber.quoteSubscribe( quoteId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Quote : " + successValue.getQuoteId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfQuoteList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on quote for quoteId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Quote. 
	 */
	protected Quote read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Quote" );

		Quote entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Quote with primary key" );
		msg.append( quoteId );
		
		QuoteFetchOneSummary fetchOneSummary = new QuoteFetchOneSummary( quoteId );

		try {
			entity = QuoteService.getQuoteInstance().getQuote( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Quote " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Quote.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Quote." );

		StringBuilder msg = new StringBuilder( "Failed to update a Quote : " );        
		Quote entity = read();
		UpdateQuoteCommand command = generateUpdateCommand();
		command.setQuoteId(entity.getQuoteId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Quote." );

			// for use later on...
			quoteId = entity.getQuoteId();

			QuoteService proxy = QuoteService.getQuoteInstance();  

			proxy.updateQuote( command ).get();

			LOGGER.info( "-- Successfully saved Quote - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + quoteId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Quote.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Quote." );

		Quote entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Quote with id " + quoteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Quote with id " + quoteId );

			throw e;
		}

		try{
			QuoteService.getQuoteInstance().delete( new DeleteQuoteCommand( entity.getQuoteId() ) ).get();
			LOGGER.info( "-- Successfully deleted Quote with id " + quoteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Quote with id " + quoteId );

			throw e;
		}
	}

	/**
	 * get all Quotes.
	 */
	protected List<Quote> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Quotes:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Quote : " );        
		List<Quote> collection  = new ArrayList<>();

		try {
			// call the static get method on the QuoteService
			collection = QuoteService.getQuoteInstance().getAllQuote();
			assertNotNull( collection, "An Empty collection of Quote was incorrectly returned.");
			
			// Now print out the values
			Quote entity = null;            
			Iterator<Quote> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getQuoteId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

